steps.script:
$l=@(Get-Content 'C:\TTiTTulares\ttittulares-mobile-trigger.log' -Tail 500)
$g=[string]($l|Where-Object{$_ -match 'NEW_CHAT_NOT_BLANK'}|Select-Object -Last 1)
$o=@{state='ok';url_kind='unknown';draft_length=0;users=0;assistants=0;clicked=[bool](@($l|Where-Object{$_ -match 'HOME_RESTORED_HISTORY; CLICK_NEW_CHAT_BOT_OWNED_TAB'}).Count)}
if($g -match 'editorLength[^0-9]*([0-9]+)'){$o.draft_length=[int]$Matches[1]}
if($g -match 'users[^0-9]*([0-9]+)'){$o.users=[int]$Matches[1]}
if($g -match 'assistants[^0-9]*([0-9]+)'){$o.assistants=[int]$Matches[1]}
if($g -match 'chatgpt.com/c/'){$o.url_kind='conversation'}
elseif($g -match 'chatgpt.com/g/'){$o.url_kind='project'}
elseif($g -match 'chatgpt.com/'){$o.url_kind='home'}
Write-Output ('TTRESULT:'+($o|ConvertTo-Json -Compress))
